import converted from '@/data/converted-documents.json';

// Originals that the GitHub Actions pipeline has converted to a sibling "<file>.pdf".
const convertedSet = new Set((converted as string[]).map(normalize));

function normalize(url: string) {
  try { return decodeURI(url); } catch { return url; }
}

/** PDF copy generated by scripts/convert-documents.py, or null when none exists. */
export function convertedPdfUrl(url: string): string | null {
  return convertedSet.has(normalize(url)) ? `${url}.pdf` : null;
}
